void renderWav(const RenderPlan&p,const fs::path&path,const ExportOptions&o,ExportControl*control){
    if(o.rate<8000||o.rate>192000||(o.bits!=16&&o.bits!=24&&o.bits!=32)||(o.channels!=1&&o.channels!=2))throw std::runtime_error("Unsupported WAV settings");double first=clamp(o.startBeat,0,p.length),last=o.endBeat>first?clamp(o.endBeat,first,p.length):p.length;if(last<=first)throw std::runtime_error("Export range is empty");
    RenderPlan offline=p;offline.loop=false;offline.length=last;auto renderer=std::make_unique<Renderer>();renderer->rate=o.rate;renderer->locate(p.clock.seconds(first)*o.rate);std::array<float,MaxBlock*2>buffer{};uint64_t music=(uint64_t)std::ceil(p.clock.duration(first,last)*o.rate),tail=(uint64_t)std::llround(clamp(o.tailSeconds,0,30)*o.rate),frames=music+tail,total=frames+p.latency,bytes=frames*o.channels*(o.bits/8);if(bytes>0xfffffff0ull)throw std::runtime_error("WAV exceeds the 4 GB RIFF limit");
    auto raw=path;raw+=L".render-float.tmp";auto temp=path;temp+=L".render.tmp";auto cancelled=[&]{if(control&&control->cancel)throw std::runtime_error("Export cancelled");};std::ofstream stage(raw,std::ios::binary);if(!stage)throw std::runtime_error("Cannot create render temporary file");try{double peak=0;for(uint64_t offset=0;offset<total;){cancelled();int count=(int)std::min<uint64_t>(MaxBlock,total-offset);renderer->render(offline,buffer.data(),count,offset<music);int skip=(int)std::min<uint64_t>(count,offset<(uint64_t)p.latency?p.latency-offset:0),use=count-skip;for(int i=skip;i<count;i++)peak=std::max(peak,o.channels==1?double(std::abs((buffer[i*2]+buffer[i*2+1])*.5f)):double(std::max(std::abs(buffer[i*2]),std::abs(buffer[i*2+1]))));stage.write((const char*)(buffer.data()+skip*2),use*2*sizeof(float));if(!stage)throw std::runtime_error("Disk full while rendering");offset+=count;if(control)control->progress=control->renderWeight*.8*offset/double(total);}stage.close();std::ifstream input(raw,std::ios::binary);std::ofstream output(temp,std::ios::binary);if(!input||!output)throw std::runtime_error("Cannot encode render output");auto u16=[&](uint16_t v){output.write((char*)&v,2);};auto u32=[&](uint32_t v){output.write((char*)&v,4);};output.write("RIFF",4);u32((uint32_t)bytes+36);output.write("WAVEfmt ",8);u32(16);u16(o.bits==32?3:1);u16(o.channels);u32(o.rate);u32(o.rate*o.channels*(o.bits/8));u16(o.channels*(o.bits/8));u16(o.bits);output.write("data",4);u32((uint32_t)bytes);double gain=o.normalize&&peak>1e-12?.99/peak:1;uint32_t random=0x71355u;auto noise=[&]{random^=random<<13;random^=random>>17;random^=random<<5;return (random&0xffffff)/16777216.;};
        for(uint64_t offset=0;offset<frames;){cancelled();int count=(int)std::min<uint64_t>(MaxBlock,frames-offset);input.read((char*)buffer.data(),count*2*sizeof(float));if(!input)throw std::runtime_error("Incomplete render temporary file");std::array<char,MaxBlock*8>encoded{};int at=0;for(int i=0;i<count;i++)for(int c=0;c<o.channels;c++){double sample=(o.channels==1?(buffer[i*2]+buffer[i*2+1])*.5:buffer[i*2+c])*gain;if(o.bits==32){float value=(float)sample;memcpy(encoded.data()+at,&value,4);at+=4;}else{double maximum=o.bits==16?32767.:8388607.;if(o.dither)sample+=(noise()-noise())/maximum;int32_t value=(int32_t)std::llround(clamp(sample,-1,1)*maximum);memcpy(encoded.data()+at,&value,o.bits/8);at+=o.bits/8;}}output.write(encoded.data(),at);if(!output)throw std::runtime_error("Disk full while encoding");offset+=count;if(control)control->progress=control->renderWeight*(.8+.2*offset/double(frames));}output.flush();if(!output)throw std::runtime_error("Cannot finish WAV output");output.close();input.close();cancelled();if(!MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Cannot replace WAV output");std::error_code ec;fs::remove(raw,ec);if(control)control->progress=control->renderWeight;
    }catch(...){stage.close();std::error_code ec;fs::remove(raw,ec);fs::remove(temp,ec);throw;}
}
#include "encode.inc"
void exportWav(const RenderPlan&p,const fs::path&path,int sampleRate){ExportOptions options;options.rate=sampleRate;renderWav(p,path,options);}
